(249753, 16154, 6405, '<td valign="top">Cool soap, 10 from me!</td>', 'Cool soap, 10 from me!', '2003-03-31 11:59:59.000000', NULL, 1),
(249754, 16172, 1344, '<td valign="top">Very nice -- I''m a big fan of simple, clean, sharp images..  I''m thinkin maybe the white border could have been a little darker or bluer or something..  It seems to stand out a bit too much.  8</td>', 'Very nice -- I''m a big fan of simple, clean, sharp images..  I''m thinkin maybe the white border could have been a little darker or bluer or something..  It seems to stand out a bit too much.  8', '2003-03-31 12:00:18.000000', NULL, 1),
(249757, 16693, 1344, '<td valign="top">Interesting, but too underexposed and that green strip along the bottom is ugly and blurry.</td>', 'Interesting, but too underexposed and that green strip along the bottom is ugly and blurry.', '2003-03-31 12:02:13.000000', NULL, 1),
(249761, 16770, 2764, '<td valign="top">why not a vertical  orientation? very nice</td>', 'why not a vertical  orientation? very nice', '2003-03-31 12:05:47.000000', NULL, 1),
(249762, 16524, 772, '<td valign="top">This is a gorgeous black and white :)  The lighting and composition are both perfect... great shot.. = 10 - setzler</td>', 'This is a gorgeous black and white :)  The lighting and composition are both perfect... great shot.. = 10 - setzler', '2003-03-31 12:05:54.000000', NULL, 1),
(249764, 16770, 772, '<td valign="top">beautiful shot... the sparks make this one stand out... great work :) = 10 - setzler</td>', 'beautiful shot... the sparks make this one stand out... great work :) = 10 - setzler', '2003-03-31 12:07:00.000000', NULL, 1),
(249772, 16702, 1344, '<td valign="top">Wonderfully sharp, but the colors are too dull for it to be a very interesting photo for me.  Maybe some post processing could have made it a WOW''er!</td>', 'Wonderfully sharp, but the colors are too dull for it to be a very interesting photo for me.  Maybe some post processing could have made it a WOW''er!', '2003-03-31 12:10:31.000000', NULL, 1),
(249773, 16633, 772, '<td valign="top">great macro :)  I''m glad you chose and old and worn baseball... that adds so much character to this shot... great work :) = 10 - setzler</td>', 'great macro :)  I''m glad you chose and old and worn baseball... that adds so much character to this shot... great work :) = 10 - setzler', '2003-03-31 12:10:55.000000', NULL, 1),
(249776, 16643, 2764, '<td valign="top">dark?</td>', 'dark?', '2003-03-31 12:12:37.000000', NULL, 1),
(249781, 16693, 2764, '<td valign="top">dark?</td>', 'dark?', '2003-03-31 12:14:32.000000', NULL, 1),
(249783, 16695, 2764, '<td valign="top">You just need those wavy heat lines behind it!</td>', 'You just need those wavy heat lines behind it!', '2003-03-31 12:15:18.000000', NULL, 1),
(249788, 16621, 1344, '<td valign="top">Don''t think the yellow thing works (for me at least)..  I was going to say you needed to correct it, but obviously that''s what you''re going for after seeing the yellowish border.  Would have liked this in B&amp;W or maybe slightly blue color toned to give it the cold steel look.</td>', 'Don''t think the yellow thing works (for me at least)..  I was going to say you needed to correct it, but obviously that''s what you''re going for after seeing the yellowish border.  Would have liked this in B&W or maybe slightly blue color toned to give it the cold steel look.', '2003-03-31 12:17:01.000000', NULL, 1),
(249802, 16196, 1717, '<td valign="top">great photo!  the detail is amazing.  the focus looks a little soft on the word quarter, but everything else is very sharp.  good job!</td>', 'great photo!  the detail is amazing.  the focus looks a little soft on the word quarter, but everything else is very sharp.  good job!', '2003-03-31 12:20:58.000000', NULL, 1),
(249814, 16760, 6328, '<td valign="top">You show nice color of the flower as it''s life decays.  It''s very distinctive with the black background.  You''ve also given it good lighting from above.</td>', 'You show nice color of the flower as it''s life decays.  It''s very distinctive with the black background.  You''ve also given it good lighting from above.', '2003-03-31 12:23:10.000000', NULL, 1),
(249819, 16295, 1344, '<td valign="top">Well done!  Nice composition and good idea.  Black border is wider horizontally than it is vertically though..</td>', 'Well done!  Nice composition and good idea.  Black border is wider horizontally than it is vertically though..', '2003-03-31 12:24:22.000000', NULL, 1),
(249822, 16572, 1717, '<td valign="top">wow!  now THAT''S a macro!  great shot...i love the lighting and the detail is amazing!  good job!</td>', 'wow!  now THAT''S a macro!  great shot...i love the lighting and the detail is amazing!  good job!', '2003-03-31 12:25:23.000000', NULL, 1),
(249824, 16726, 6328, '<td valign="top">You''ve really attempted to give us a good photograph here.  the colours of the base (iron) are nice as is the background, but unfortunately, your flame is so overpowering and bright that it''s blown out the whole top of the photo and you can''t really see any flame as such.</td>', 'You''ve really attempted to give us a good photograph here.  the colours of the base (iron) are nice as is the background, but unfortunately, your flame is so overpowering and bright that it''s blown out the whole top of the photo and you can''t really see any flame as such.', '2003-03-31 12:25:50.000000', NULL, 1),
(249827, 16282, 6328, '<td valign="top">Really nice macro.  Good colours of the two brass, great lighting for being so close too.  You''ve done a really good job here.</td>', 'Really nice macro.  Good colours of the two brass, great lighting for being so close too.  You''ve done a really good job here.', '2003-03-31 12:27:24.000000', NULL, 1),
