(250610, 16727, 5391, '<td valign="top">Awwww...  I had one of these guys once, and her name was "Buddy".  VERY nice shot.  Good focus.  A couple of his little pin feathers need preening, but this is a better shot than I ever got of my little guy.</td>', 'Awwww...  I had one of these guys once, and her name was "Buddy".  VERY nice shot.  Good focus.  A couple of his little pin feathers need preening, but this is a better shot than I ever got of my little guy.', '2003-03-31 18:21:02.000000', NULL, 1),
(250646, 16576, 5112, '<td valign="top">How did you do that?!?!  This is beautiful.</td>', 'How did you do that?!?!  This is beautiful.', '2003-03-31 18:38:21.000000', NULL, 1),
(250676, 16702, 6328, '<td valign="top">Lovely colours in the various stones.  Good lighting, can''t do anything with the bouncing of light with stones.  How come you show a red border on the bottom, but not anywhere else?  In a contest, you''d get tossed.  Here, you only get a 6 instead of a 7.  Sorry.</td>', 'Lovely colours in the various stones.  Good lighting, can''t do anything with the bouncing of light with stones.  How come you show a red border on the bottom, but not anywhere else?  In a contest, you''d get tossed.  Here, you only get a 6 instead of a 7.  Sorry.', '2003-03-31 18:59:25.000000', NULL, 1),
(250689, 16742, 6025, '<td valign="top">Macromacro metaphotography? ;) Cool shot.</td>', 'Macromacro metaphotography? ;) Cool shot.', '2003-03-31 19:18:23.000000', NULL, 1),
(250690, 16178, 6025, '<td valign="top">On my monitor it seems like your white balance has taken a beating - the picture is blue! Not a bad idea though. The light is a bit harsh (flash?). (6)</td>', 'On my monitor it seems like your white balance has taken a beating - the picture is blue! Not a bad idea though. The light is a bit harsh (flash?). (6)', '2003-03-31 19:20:56.000000', NULL, 1),
(250693, 16172, 6025, '<td valign="top">Stylish. Cool crop and nice colours. Nice and sharp as well. Good job. (8)</td>', 'Stylish. Cool crop and nice colours. Nice and sharp as well. Good job. (8)', '2003-03-31 19:21:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(250694, 16647, 6025, '<td valign="top">Defo the cutest picture in the challenge. Then again, I am a cat person. Nice techniwue, but it sems a bit over-sharpened. (8)</td>', 'Defo the cutest picture in the challenge. Then again, I am a cat person. Nice techniwue, but it sems a bit over-sharpened. (8)', '2003-03-31 19:22:43.000000', NULL, 1),
(250705, 16542, 6328, '<td valign="top">Nice shot of my beer.  Good lighting too.  I think it\''s a good advertising shot?  Tell me though, did you drink my beer, too??  What''s all the little white spots on the bottom of the bottle?  Good focus also.</td>', 'Nice shot of my beer.  Good lighting too.  I think it\''s a good advertising shot?  Tell me though, did you drink my beer, too??  What''s all the little white spots on the bottom of the bottle?  Good focus also.', '2003-03-31 19:32:28.000000', NULL, 1),
(250713, 16597, 6900, '<td valign="top">It''s too bad about the hot pixels - a very nice ''symmetrical'' macro.</td>', 'It''s too bad about the hot pixels - a very nice ''symmetrical'' macro.', '2003-03-31 19:39:49.000000', NULL, 1),
(250715, 16574, 472, '<td valign="top">this is way cool. i like macro shots like this where you''re ''down in the action'', part of the story if you will.  you''ve conveyed the feeling well of being surrounded and intimidated by tall powerful enemies, using selective dof and foreground blur.  the pawn and king have an old man and little child type feel.  top notch.</td>', 'this is way cool. i like macro shots like this where you''re ''down in the action'', part of the story if you will.  you''ve conveyed the feeling well of being surrounded and intimidated by tall powerful enemies, using selective dof and foreground blur.  the pawn and king have an old man and little child type feel.  top notch.', '2003-03-31 19:40:12.000000', NULL, 1),
(250718, 16623, 472, '<td valign="top">great lighting and good depth of field. the composition and color are also nice.  i would maybe have liked the blower a little closer to the camera ie bigger in the frame</td>', 'great lighting and good depth of field. the composition and color are also nice.  i would maybe have liked the blower a little closer to the camera ie bigger in the frame', '2003-03-31 19:41:29.000000', NULL, 1),
(250720, 16545, 472, '<td valign="top">very amniotic. is this an egg?</td>', 'very amniotic. is this an egg?', '2003-03-31 19:41:52.000000', NULL, 1),
(250724, 16347, 472, '<td valign="top">too much light.  it''s exposed fine, but because everything is so evenly illuminated there''s no mystery to this rather ordinary household object.  also the color of the light is rather cold.</td>', 'too much light.  it''s exposed fine, but because everything is so evenly illuminated there''s no mystery to this rather ordinary household object.  also the color of the light is rather cold.', '2003-03-31 19:43:27.000000', NULL, 1),
(250726, 16483, 6900, '<td valign="top">Lots and lots of hot pixels, a bit out of focus - but I like the subject and the lighting.</td>', 'Lots and lots of hot pixels, a bit out of focus - but I like the subject and the lighting.', '2003-03-31 19:44:02.000000', NULL, 1),
(250728, 16731, 472, '<td valign="top">fabulous detail. the black and white brings it out, and the selective dof works great.</td>', 'fabulous detail. the black and white brings it out, and the selective dof works great.', '2003-03-31 19:44:04.000000', NULL, 1),
(250732, 16647, 2158, '<td valign="top">I wish I could vote - this would definitely rate 10.</td>', 'I wish I could vote - this would definitely rate 10.', '2003-03-31 19:45:18.000000', NULL, 1),
(250734, 16580, 6900, '<td valign="top">I''m not sure I like the bg color, but I''m not sure what I''d use there.</td>', 'I''m not sure I like the bg color, but I''m not sure what I''d use there.', '2003-03-31 19:45:57.000000', NULL, 1),
(250750, 16264, 6900, '<td valign="top">At this point, I''m marking it down because it''s not very creative.  This is an obvious copy of Setzler''s flag, and considering someone ELSE just did it with time last week, it''s nice, but...<br/>I do like your choice of subject to try it with.  I just wish it was your personal gallery shot and not an entry into the same contest we''ve seen this in b4.</td>', 'At this point, I''m marking it down because it''s not very creative.  This is an obvious copy of Setzler''s flag, and considering someone ELSE just did it with time last week, it''s nice, but...I do like your choice of subject to try it with.  I just wish it was your personal gallery shot and not an entry into the same contest we''ve seen this in b4.', '2003-03-31 19:55:54.000000', NULL, 1),
(250756, 16295, 6900, '<td valign="top">Amusing!  And nice use of color.</td>', 'Amusing!  And nice use of color.', '2003-03-31 19:59:18.000000', NULL, 1),
(250804, 16551, 6504, '<td valign="top">Good idea.  I thought I was the only one who still has a pin cushion around.<br/>The colors are good, the clarity of the pins, thread is good.  Very good photo all around.</td>', 'Good idea.  I thought I was the only one who still has a pin cushion around.The colors are good, the clarity of the pins, thread is good.  Very good photo all around.', '2003-03-31 21:10:43.000000', NULL, 1),
(250806, 16693, 6504, '<td valign="top">Why not more light?  You have a good idea, but it gets a little lost in the darkness.</td>', 'Why not more light?  You have a good idea, but it gets a little lost in the darkness.', '2003-03-31 21:11:26.000000', NULL, 1),
(250808, 16647, 7190, '<td valign="top">not a cat person but this is a great shot the tip tongue really adds to the shot</td>', 'not a cat person but this is a great shot the tip tongue really adds to the shot', '2003-03-31 21:12:46.000000', NULL, 1),
(250823, 16382, 4793, '<td valign="top">Very nice shot, nice colors, different way of shooting flowers.</td>', 'Very nice shot, nice colors, different way of shooting flowers.', '2003-03-31 21:33:20.000000', NULL, 1),
