(251125, 16733, 5767, '<td valign="top">A little overexposed (from flash probably), but your creativity should be rewarded for thinking of this.</td>', 'A little overexposed (from flash probably), but your creativity should be rewarded for thinking of this.', '2003-04-01 01:59:17.000000', NULL, 1),
(251126, 16629, 6600, '<td valign="top">Great idea, neat shot!  With the focal point being the tail section (based on focus), I might have replaced the tail section with a nice new one for this pic.</td>', 'Great idea, neat shot!  With the focal point being the tail section (based on focus), I might have replaced the tail section with a nice new one for this pic.', '2003-04-01 01:59:19.000000', NULL, 1),
