(251142, 16574, 5767, '<td valign="top">Great perspective and use of focus.  This is very well done.</td>', 'Great perspective and use of focus.  This is very well done.', '2003-04-01 02:05:06.000000', NULL, 1),
(251143, 16571, 6600, '<td valign="top">Great idea!  I really like the color contrast.  (Don''t know if it would be possible, but I would try to get a tad more definition on the black portion of the knob).</td>', 'Great idea!  I really like the color contrast.  (Don''t know if it would be possible, but I would try to get a tad more definition on the black portion of the knob).', '2003-04-01 02:05:51.000000', NULL, 1),
(251144, 16039, 5767, '<td valign="top">This image is very out of focus which is the main reason for the low score.  I think the concept is a good one, though.</td>', 'This image is very out of focus which is the main reason for the low score.  I think the concept is a good one, though.', '2003-04-01 02:05:55.000000', NULL, 1),
(251145, 16325, 6405, '<td valign="top">beautiful background and lighting, good leading lines, but boring subject 8 here!</td>', 'beautiful background and lighting, good leading lines, but boring subject 8 here!', '2003-04-01 02:05:56.000000', NULL, 1),
(251146, 16161, 5767, '<td valign="top">this one leaves me wondering what is going on here.  I like it a lot.  You''ve captured some interesting color bursts as well.</td>', 'this one leaves me wondering what is going on here.  I like it a lot.  You''ve captured some interesting color bursts as well.', '2003-04-01 02:06:32.000000', NULL, 1),
