(253150, 16509, 2472, '<td valign="top">Very, very beautiful. Marvelous elegance and refinement. Perfect crop. My choice to win.</td>', 'Very, very beautiful. Marvelous elegance and refinement. Perfect crop. My choice to win.', '2003-04-02 20:16:24.000000', NULL, 1),
(253164, 16633, 1280, '<td valign="top">I''m not a baseball fan, though I am an American.  You did a great job on this!!!</td>', 'I''m not a baseball fan, though I am an American.  You did a great job on this!!!', '2003-04-02 20:44:52.000000', NULL, 1),
(253168, 16313, 6667, '<td valign="top">One week too early?!</td>', 'One week too early?!', '2003-04-02 20:49:39.000000', NULL, 1),
(253172, 16684, 6667, '<td valign="top">One week too early, no?!  Nice shot</td>', 'One week too early, no?!  Nice shot', '2003-04-02 20:53:46.000000', NULL, 1),
(253174, 16643, 6667, '<td valign="top">Very, very nice.</td>', 'Very, very nice.', '2003-04-02 20:58:34.000000', NULL, 1),
(253175, 16572, 6667, '<td valign="top">Just a great idea and great shot.  Simple but neat.</td>', 'Just a great idea and great shot.  Simple but neat.', '2003-04-02 21:01:22.000000', NULL, 1),
(253176, 16559, 6667, '<td valign="top">Boy!  Is this shot just a week too early?  Great color.  Why even include the edge of the plate?</td>', 'Boy!  Is this shot just a week too early?  Great color.  Why even include the edge of the plate?', '2003-04-02 21:03:58.000000', NULL, 1),
(253281, 16574, 6328, '<td valign="top">Really nice the way you''ve presented this photograph.  I think it''s one that perhaps you would benefit from showing us how you did it.  Excellent color on the front chess pieces, the yellow, speckled green, white/beige.</td>', 'Really nice the way you''ve presented this photograph.  I think it''s one that perhaps you would benefit from showing us how you did it.  Excellent color on the front chess pieces, the yellow, speckled green, white/beige.', '2003-04-02 23:17:20.000000', NULL, 1),
(253283, 16742, 6328, '<td valign="top">Ah, yes.  Very nice indeed.  Initiative, imagination, freshness, great idea. . .<br/>nice colours, great focus, good dof, really nice shot.  Good job indeed.  The detail is excellent!  Very good lighting too.</td>', 'Ah, yes.  Very nice indeed.  Initiative, imagination, freshness, great idea. . .nice colours, great focus, good dof, really nice shot.  Good job indeed.  The detail is excellent!  Very good lighting too.', '2003-04-02 23:19:43.000000', NULL, 1),
(253284, 16224, 6328, '<td valign="top">Beautiful Colours!  Love the shadow.  Great lighting.  The focus is right on.  <br/>What else can I say?<br/>I don''t like that shadow at the top, that''s all.  Very distracting.  Why is it there?<br/>In all honesty, I would have given you an eight if it weren''t there.</td>', 'Beautiful Colours!  Love the shadow.  Great lighting.  The focus is right on.  What else can I say?I don''t like that shadow at the top, that''s all.  Very distracting.  Why is it there?In all honesty, I would have given you an eight if it weren''t there.', '2003-04-02 23:22:41.000000', NULL, 1),
(253285, 16196, 6328, '<td valign="top">Nice colouring here of the various coins.  Good lighting, good focus.</td>', 'Nice colouring here of the various coins.  Good lighting, good focus.', '2003-04-02 23:24:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(253289, 16715, 6328, '<td valign="top">Now this is a very unusual subject to photograph.  Nicely framed, good focus, nice detail on what''s his name and his vehicle?</td>', 'Now this is a very unusual subject to photograph.  Nicely framed, good focus, nice detail on what''s his name and his vehicle?', '2003-04-02 23:26:48.000000', NULL, 1),
(253290, 16483, 6328, '<td valign="top">Your title is "Miniature Flowers" but your flowers are out of focus.  Was this deliberate?  Part of the Stem and the base is in focus, but that''s all.  Is this what you intended?</td>', 'Your title is "Miniature Flowers" but your flowers are out of focus.  Was this deliberate?  Part of the Stem and the base is in focus, but that''s all.  Is this what you intended?', '2003-04-02 23:29:49.000000', NULL, 1),
(253291, 16727, 6328, '<td valign="top">Hey, nice colours here on the Bird, excellent focus and lighting too.  Great detail.<br/>You''ve done a great job in photographing your "buddy".</td>', 'Hey, nice colours here on the Bird, excellent focus and lighting too.  Great detail.You''ve done a great job in photographing your "buddy".', '2003-04-02 23:31:46.000000', NULL, 1),
(253292, 16731, 6328, '<td valign="top">A bit striking for a Black and White photograph.  Nice focus and lighting, good detail.</td>', 'A bit striking for a Black and White photograph.  Nice focus and lighting, good detail.', '2003-04-02 23:33:29.000000', NULL, 1),
(253293, 16661, 6328, '<td valign="top">Great idea and really different for a photo Challenge.  You show good detail in your photograph, nice lighting, good focus, perhaps a little too bright on the bottom right, but overall, a really good shot.</td>', 'Great idea and really different for a photo Challenge.  You show good detail in your photograph, nice lighting, good focus, perhaps a little too bright on the bottom right, but overall, a really good shot.', '2003-04-02 23:35:17.000000', NULL, 1),
(253295, 16099, 6328, '<td valign="top">Nice macro.  really close focus, good lighting.  nice colour.</td>', 'Nice macro.  really close focus, good lighting.  nice colour.', '2003-04-02 23:38:54.000000', NULL, 1),
(253296, 16346, 6328, '<td valign="top">Nice close-up shot.  Good color.  Something different, unusual photograph.</td>', 'Nice close-up shot.  Good color.  Something different, unusual photograph.', '2003-04-02 23:43:18.000000', NULL, 1),
(253300, 16755, 6328, '<td valign="top">The colours make this look cool and fascinating.  Good focus, good lighting too.<br/>Good visual impact when you first look at it.</td>', 'The colours make this look cool and fascinating.  Good focus, good lighting too.Good visual impact when you first look at it.', '2003-04-02 23:48:52.000000', NULL, 1),
(253303, 16473, 6328, '<td valign="top">Really nice shot, I like the way you''ve captured the bubbles caught on the wedges,and the yellow colour is just great.</td>', 'Really nice shot, I like the way you''ve captured the bubbles caught on the wedges,and the yellow colour is just great.', '2003-04-02 23:51:08.000000', NULL, 1),
(253307, 16284, 6328, '<td valign="top">Absolutely beautiful.  Great lighting landing on this beautiful creature.  I wish I could see this in my garden right now!  Lovely colouring of the yellow and pink with that tiny touch of green.</td>', 'Absolutely beautiful.  Great lighting landing on this beautiful creature.  I wish I could see this in my garden right now!  Lovely colouring of the yellow and pink with that tiny touch of green.', '2003-04-02 23:54:59.000000', NULL, 1),
(253321, 16363, 7102, '<td valign="top">Nice shot....a bit hot at the 10 and 11 o''clock areas. Nice subject though.</td>', 'Nice shot....a bit hot at the 10 and 11 o''clock areas. Nice subject though.', '2003-04-03 00:19:56.000000', NULL, 1),
(253460, 16702, 3540, '<td valign="top">Nice colors.   Good framing and I like that there is a definite focal point of this shot</td>', 'Nice colors.   Good framing and I like that there is a definite focal point of this shot', '2003-04-03 06:25:24.000000', NULL, 1),
(253461, 16760, 3540, '<td valign="top">Excellent color and detail.  Wonderfully crisp and clean image.  Looks like a 10 to me</td>', 'Excellent color and detail.  Wonderfully crisp and clean image.  Looks like a 10 to me', '2003-04-03 06:26:53.000000', NULL, 1),
(253473, 16771, 1829, '<td valign="top">Excellent lighting, clarity and composition.  The dof is very well done also.  Great choice of subject to photograph too.  Nice job and GL in this weeks challenge.</td>', 'Excellent lighting, clarity and composition.  The dof is very well done also.  Great choice of subject to photograph too.  Nice job and GL in this weeks challenge.', '2003-04-03 06:50:14.000000', NULL, 1),
(253556, 16763, 3585, '<td valign="top">As far as dead bugs go, this is a pretty good one. 8</td>', 'As far as dead bugs go, this is a pretty good one. 8', '2003-04-03 10:35:37.000000', NULL, 1),
(253557, 16580, 3585, '<td valign="top">Revolting and well done, 8</td>', 'Revolting and well done, 8', '2003-04-03 10:38:29.000000', NULL, 1),
(253649, 16765, 675, '<td valign="top">i really like coin macros...the lighting is the hardest part really...it''s a little to hot on the top half of the coin though</td>', 'i really like coin macros...the lighting is the hardest part really...it''s a little to hot on the top half of the coin though', '2003-04-03 15:11:15.000000', NULL, 1),
(253650, 16623, 675, '<td valign="top">the bubbles aren''t in focus really. it''s a good idea though, if you could pull that off<br/></td>', 'the bubbles aren''t in focus really. it''s a good idea though, if you could pull that off', '2003-04-03 15:11:55.000000', NULL, 1),
(253654, 16461, 1005, '<td valign="top">Good emotion conveyed with the darkness of this image, good detail, too.  But the overall lighting doesn''t seem great, the glare off the statue is everywhere and just a bit too heavy for an accent, while a good portion of the statue isn''t lite at all.  Possible suggestion - softer lighting from two sides might help both issues.  On the whole, I like it.  6 Swash</td>', 'Good emotion conveyed with the darkness of this image, good detail, too.  But the overall lighting doesn''t seem great, the glare off the statue is everywhere and just a bit too heavy for an accent, while a good portion of the statue isn''t lite at all.  Possible suggestion - softer lighting from two sides might help both issues.  On the whole, I like it.  6 Swash', '2003-04-03 15:12:46.000000', NULL, 1),
(253659, 16168, 1005, '<td valign="top">I love cats and on the positive side - I don''t think I''ver ever seen a photo of just the back half (original), but there''s a reason for that, much less to look at.  The glare on the white fur is harsh.  Focus on the feet is pretty good and the color of it''s feet pads is nicely pink.  6 Swash</td>', 'I love cats and on the positive side - I don''t think I''ver ever seen a photo of just the back half (original), but there''s a reason for that, much less to look at.  The glare on the white fur is harsh.  Focus on the feet is pretty good and the color of it''s feet pads is nicely pink.  6 Swash', '2003-04-03 15:15:58.000000', NULL, 1),
(253663, 16258, 1005, '<td valign="top">Looks pretty hot to me!  Focus seems to be on the upper portion of the photo (why not the whole?).  Color seems about right.  Interest - I thought this might be an interesting shot too, but decided against it (low to moderate).  The drip tray seems nicely clean (a second reason why I didn''t go this direction, I''d have to clean the tray!).    6   Rob the Swash</td>', 'Looks pretty hot to me!  Focus seems to be on the upper portion of the photo (why not the whole?).  Color seems about right.  Interest - I thought this might be an interesting shot too, but decided against it (low to moderate).  The drip tray seems nicely clean (a second reason why I didn''t go this direction, I''d have to clean the tray!).    6   Rob the Swash', '2003-04-03 15:18:48.000000', NULL, 1),
(253664, 16731, 675, '<td valign="top">i like this photo, it has a spooky feel to me. it is truly a work of art. i like the way the depth of field moves in and out across the photo</td>', 'i like this photo, it has a spooky feel to me. it is truly a work of art. i like the way the depth of field moves in and out across the photo', '2003-04-03 15:19:14.000000', NULL, 1),
(253665, 16543, 675, '<td valign="top">SLIME!!!</td>', 'SLIME!!!', '2003-04-03 15:20:06.000000', NULL, 1),
(253667, 16551, 675, '<td valign="top">quality...i''m just taking a stab, but it seems like there is too much contrast or not enough depth of field because i don''t really like how the red weave runs together<br/></td>', 'quality...i''m just taking a stab, but it seems like there is too much contrast or not enough depth of field because i don''t really like how the red weave runs together', '2003-04-03 15:21:30.000000', NULL, 1),
(253669, 16158, 1005, '<td valign="top">Sharp photo!  Seems overly exposed, I assume to help blank out the background, but to me, it makes it seem more unworldly (and less photographically).  Looks like the painter needed more tape (or to actually use it   -  proof of good detail).  It''s very well done, but I''m not a fan of over-exposure (I feel this was deliberate).  I''m going to offer you one extra point (due to my bias), score raised from 6 to 7.  Rob the Swash</td>', 'Sharp photo!  Seems overly exposed, I assume to help blank out the background, but to me, it makes it seem more unworldly (and less photographically).  Looks like the painter needed more tape (or to actually use it   -  proof of good detail).  It''s very well done, but I''m not a fan of over-exposure (I feel this was deliberate).  I''m going to offer you one extra point (due to my bias), score raised from 6 to 7.  Rob the Swash', '2003-04-03 15:22:59.000000', NULL, 1),
(253705, 16535, 675, '<td valign="top">i like the nice glow underneath the lighted ridge there, but there isn''t enough sharpness in the photo. however, the parts that are in focus are a good example of macro photography</td>', 'i like the nice glow underneath the lighted ridge there, but there isn''t enough sharpness in the photo. however, the parts that are in focus are a good example of macro photography', '2003-04-03 15:42:34.000000', NULL, 1),
(253730, 16462, 5266, '<td valign="top">Love the shadow, and for once I feel the border helps the photo.  Nice work</td>', 'Love the shadow, and for once I feel the border helps the photo.  Nice work', '2003-04-03 16:31:42.000000', NULL, 1),
(253732, 16750, 5266, '<td valign="top">A bit overexposed in places and very grainy.</td>', 'A bit overexposed in places and very grainy.', '2003-04-03 16:33:21.000000', NULL, 1),
(253733, 16203, 5266, '<td valign="top">I think this would have been really cool with a light behind the crystal, But right now it''s a bit flat.  I love the colors:)</td>', 'I think this would have been really cool with a light behind the crystal, But right now it''s a bit flat.  I love the colors:)', '2003-04-03 16:34:08.000000', NULL, 1),
(253735, 16647, 5266, '<td valign="top">BEAUTIFUL!!!!  The tongue makes this photo.  Great focus on the kitty, but clean out the gunk in the eye, OK?  Love the whiskers</td>', 'BEAUTIFUL!!!!  The tongue makes this photo.  Great focus on the kitty, but clean out the gunk in the eye, OK?  Love the whiskers', '2003-04-03 16:44:16.000000', NULL, 1),
(253751, 16172, 772, '<td valign="top">very nicely done macro... the detail is excellent an the choice of lighting works very well here also... great shot :) - setzler</td>', 'very nicely done macro... the detail is excellent an the choice of lighting works very well here also... great shot :) - setzler', '2003-04-03 17:19:32.000000', NULL, 1),
(253814, 16695, 772, '<td valign="top">This is a really neat image.  I love the shallow depth of field and the way it creates a nice cloudy blue environment behind the car.  It also draws my eye right to the front tip of the car... great work :) - setzler</td>', 'This is a really neat image.  I love the shallow depth of field and the way it creates a nice cloudy blue environment behind the car.  It also draws my eye right to the front tip of the car... great work :) - setzler', '2003-04-03 19:54:22.000000', NULL, 1),
(253818, 16760, 3015, '<td valign="top">I like this very much. It is old and with great beauty. A sign of great wisdom. After the challenge I will like to make this a favorte picture for me.</td>', 'I like this very much. It is old and with great beauty. A sign of great wisdom. After the challenge I will like to make this a favorte picture for me.', '2003-04-03 20:07:13.000000', NULL, 1),
(253820, 16576, 255, '<td valign="top">wow--this is gorgeous! i cant for the life of me figure out how you got that background! the colors and lighting are perfect. awesome work!</td>', 'wow--this is gorgeous! i cant for the life of me figure out how you got that background! the colors and lighting are perfect. awesome work!', '2003-04-03 20:09:31.000000', NULL, 1),
(253824, 16440, 7671, '<td valign="top">In my opinion this serves to prove that sometimes the simplest things are the most effective. The picture is clear (and I can almost feel the cold!). Great shot.</td>', 'In my opinion this serves to prove that sometimes the simplest things are the most effective. The picture is clear (and I can almost feel the cold!). Great shot.', '2003-04-03 20:29:47.000000', NULL, 1),
(253830, 16497, 6505, '<td valign="top">Very nice.  Focus is a tad soft.  Lighting is excellent for me.  Good job!</td>', 'Very nice.  Focus is a tad soft.  Lighting is excellent for me.  Good job!', '2003-04-03 20:44:02.000000', NULL, 1),
(253860, 16727, 554, '<td valign="top">love your bird.....nice photo</td>', 'love your bird.....nice photo', '2003-04-03 22:21:03.000000', NULL, 1),
(253862, 16687, 6011, '<td valign="top">This is really pretty.</td>', 'This is really pretty.', '2003-04-03 22:28:16.000000', NULL, 1),
(253864, 16440, 6523, '<td valign="top">I love this picture -- especially the color.  Good work!</td>', 'I love this picture -- especially the color.  Good work!', '2003-04-03 22:37:23.000000', NULL, 1),
(253865, 16046, 6523, '<td valign="top">I really like the focus on this photo.  Good work!</td>', 'I really like the focus on this photo.  Good work!', '2003-04-03 22:38:04.000000', NULL, 1),
(253867, 16580, 6523, '<td valign="top">I don''t know what a chocolate cream bun is -- never saw anything that was called that, anyway.  Whatever it is, you''ve made it look ABSOLUTELY DELICIOUS here!  Good job!</td>', 'I don''t know what a chocolate cream bun is -- never saw anything that was called that, anyway.  Whatever it is, you''ve made it look ABSOLUTELY DELICIOUS here!  Good job!', '2003-04-03 22:41:11.000000', NULL, 1),
(253883, 16509, 5044, '<td valign="top">nice soft tones. good composition, too.</td>', 'nice soft tones. good composition, too.', '2003-04-03 23:17:57.000000', NULL, 1),
(253887, 16693, 6803, '<td valign="top">nice idea, a little dark  though</td>', 'nice idea, a little dark  though', '2003-04-03 23:22:09.000000', NULL, 1),
(253889, 16441, 6803, '<td valign="top">interesting angle. A little bla...different colored paper would have worked better</td>', 'interesting angle. A little bla...different colored paper would have worked better', '2003-04-03 23:26:39.000000', NULL, 1),
(253890, 16264, 5044, '<td valign="top">Where do all you people keep your zebras? I can never find my zebra when I need it.... Great shot, but I''ve seen too many of these shots lately.</td>', 'Where do all you people keep your zebras? I can never find my zebra when I need it.... Great shot, but I''ve seen too many of these shots lately.', '2003-04-03 23:26:42.000000', NULL, 1),
(253911, 16264, 6325, '<td valign="top">The various sizes of droplets gives depth.</td>', 'The various sizes of droplets gives depth.', '2003-04-04 01:06:30.000000', NULL, 1),
(253912, 16737, 6325, '<td valign="top">Good execution.</td>', 'Good execution.', '2003-04-04 01:07:45.000000', NULL, 1),
(253916, 16310, 6325, '<td valign="top">Nice tones. Like the bright area as a focal point.</td>', 'Nice tones. Like the bright area as a focal point.', '2003-04-04 01:10:21.000000', NULL, 1),
(253917, 16496, 6325, '<td valign="top">Interesting composition.</td>', 'Interesting composition.', '2003-04-04 01:13:06.000000', NULL, 1),
(253918, 16681, 6325, '<td valign="top">Nice, soft color.</td>', 'Nice, soft color.', '2003-04-04 01:14:22.000000', NULL, 1),
(253921, 16678, 6325, '<td valign="top">Very colorful. I would like to have seen more of the image in focus and a different background.</td>', 'Very colorful. I would like to have seen more of the image in focus and a different background.', '2003-04-04 01:16:51.000000', NULL, 1),
