(253929, 16224, 6325, '<td valign="top">Wish you had moved in closer on the wonderful purple.</td>', 'Wish you had moved in closer on the wonderful purple.', '2003-04-04 01:26:16.000000', NULL, 1),
(253931, 16346, 6325, '<td valign="top">Very nice detail and focus. Well done.</td>', 'Very nice detail and focus. Well done.', '2003-04-04 01:28:02.000000', NULL, 1),
(253932, 16539, 675, '<td valign="top">focus is pretty much on, the color is really overdone though i think</td>', 'focus is pretty much on, the color is really overdone though i think', '2003-04-04 01:41:30.000000', NULL, 1),
(253933, 16154, 675, '<td valign="top">a technically good macro, but doesn''t stand out in composition or meaning when compared to other photos. in my opinion of course</td>', 'a technically good macro, but doesn''t stand out in composition or meaning when compared to other photos. in my opinion of course', '2003-04-04 01:43:11.000000', NULL, 1),
(253935, 16079, 675, '<td valign="top">interesting photo, the lighting is too harsh on the top right corner, and teh focus isn''t quite there. nice creativity though</td>', 'interesting photo, the lighting is too harsh on the top right corner, and teh focus isn''t quite there. nice creativity though', '2003-04-04 01:44:12.000000', NULL, 1),
(253936, 16727, 675, '<td valign="top">excellent work. i like the use of depth of field</td>', 'excellent work. i like the use of depth of field', '2003-04-04 01:45:01.000000', NULL, 1),
(253938, 16755, 675, '<td valign="top">out of focus</td>', 'out of focus', '2003-04-04 01:45:32.000000', NULL, 1),
(253939, 16759, 675, '<td valign="top">this is a great photo.  it''s hard to do that!  i like the use of tones and grain. hopefully you aren''t taking too much flack for that, it works here. good shot</td>', 'this is a great photo.  it''s hard to do that!  i like the use of tones and grain. hopefully you aren''t taking too much flack for that, it works here. good shot', '2003-04-04 01:46:41.000000', NULL, 1),
(253940, 16485, 675, '<td valign="top">need more depth of field. only the right side of the photo is in focus, and the plastic bag is out of focus.</td>', 'need more depth of field. only the right side of the photo is in focus, and the plastic bag is out of focus.', '2003-04-04 01:48:55.000000', NULL, 1),
(253941, 16678, 675, '<td valign="top">excellent use of depth of field...i bet you wish you would have saved this inspiration for the color challenge. anywya.  the only problems i have are the background, which is uninteresting. black velvet would work nicely.  there is too much grain suggesting either you oversaturated the colors or you didn''t have enough light. and also that spot up in the corner.  still a good photo, and one of the better definitions of a macro in the challenge</td>', 'excellent use of depth of field...i bet you wish you would have saved this inspiration for the color challenge. anywya.  the only problems i have are the background, which is uninteresting. black velvet would work nicely.  there is too much grain suggesting either you oversaturated the colors or you didn''t have enough light. and also that spot up in the corner.  still a good photo, and one of the better definitions of a macro in the challenge', '2003-04-04 01:51:50.000000', NULL, 1),
