INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(254897, 16172, 1717, '<td valign="top">i really like this.  simple and uncluttered and i really like the crop.  great color, too.</td>', 'i really like this.  simple and uncluttered and i really like the crop.  great color, too.', '2003-04-06 00:35:48.000000', NULL, 1),
(254898, 16517, 1717, '<td valign="top">beautiful!  great colors and focus.</td>', 'beautiful!  great colors and focus.', '2003-04-06 00:38:17.000000', NULL, 1),
(254899, 16717, 1379, '<td valign="top">I love the context of this shot. Great details.</td>', 'I love the context of this shot. Great details.', '2003-04-06 00:41:28.000000', NULL, 1),
(254900, 16759, 1717, '<td valign="top">oooh...scary! :)  great shot...the sepia works well here.  well done!</td>', 'oooh...scary! :)  great shot...the sepia works well here.  well done!', '2003-04-06 00:41:58.000000', NULL, 1),
