(254959, 16535, 2780, '<td valign="top">Very nice abstract. 10</td>', 'Very nice abstract. 10', '2003-04-06 06:57:14.000000', NULL, 1),
(254960, 16684, 2780, '<td valign="top">Very good composition, and the colours look great. Good contrasts too, 9.</td>', 'Very good composition, and the colours look great. Good contrasts too, 9.', '2003-04-06 06:57:58.000000', NULL, 1),
(254961, 16692, 2780, '<td valign="top">This is great. I would love to know how you did it. 9</td>', 'This is great. I would love to know how you did it. 9', '2003-04-06 06:58:29.000000', NULL, 1),
